function login() {}

function gengxin() {
    java.toast('正在检查...');
    var baseUrls = [
        {name: 'GitHub', color: '#24292f', url: 'https://raw.githubusercontent.com/fengying915/yuedu/main/fy.json'},
        {name: 'Gitee', color: '#c71d23', url: 'https://gitee.com/fengying915/yuedu/raw/main/fy.json'},
        {name: 'CDN', color: '#f4812f', url: 'https://cdn.jsdelivr.net/gh/fengying915/yuedu@main/fy.json'}
    ];

    var rb = null;
    var errs = [];
    for (var i = 0; i < baseUrls.length; i++) {
        try {
            var body = java.get(baseUrls[i].url, {'User-Agent': 'Mozilla/5.0'}).body();
            var json = JSON.parse(body)[0];
            var ver = json.jsLib.match(/banben="([^"]+)"/)[1];
            if (ver) { rb = ver; break; }
        } catch (e) {
            errs.push(baseUrls[i].name + ': ' + e.message);
        }
    }
    if (!rb) {
        java.toast('检查失败，所有源均不可用');
        java.log('检查失败: ' + errs.join(' | '));
        return;
    }

    var isNew = rb != banben;
    var statusText = isNew ? '发现新版本' : '您已是最新版本';
    var statusClass = isNew ? 'update-available' : 'up-to-date';
    var indicatorClass = isNew ? 'update-needed' : 'is-latest';
    var currentStatusClass = isNew ? 'status-outdated' : 'status-latest';
    var latestStatusText = isNew ? '最新版本' : '最新版本';

    var btnHtml = '';
    if (isNew) {
        for (var j = 0; j < baseUrls.length; j++) {
            btnHtml += `
                <a href="legado://import/importonline?src=${encodeURIComponent(baseUrls[j].url)}" 
                   class="button" style="background:${baseUrls[j].color};">
                     ${baseUrls[j].name} 导入
                </a>
            `;
        }
    }

    var html = `
<!DOCTYPE html>
<html lang="zh-CN">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>更新检测</title>
  <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css" />
  <link rel="stylesheet" href="https://cdn.jsdelivr.net/gh/fengying915/yuedu2@main/gengxin.css" />
</head>
<body>
  <div class="decoration circle"></div>
  <div class="decoration square"></div>

  <div class="container">
    <div class="header">
      <div class="header-icon"><i class="fas fa-book"></i></div>
      <h1>枫影的订阅</h1>
      <p>版本检测 · 推荐使用阅读 <a href="https://fengying915.github.io/legado.html">Sigma</a></p>
    </div>

    <div class="version-comparison">
      <div class="version-card current-version">
        <div class="version-status ${currentStatusClass}">${isNew ? '待更新' : '最新'}</div>
        <h3><i class="fas fa-cube"></i> 当前版本</h3>
        <div class="version-number">${banben}</div>
        <div class="version-date">本地版本</div>
      </div>

      <div class="version-indicator ${indicatorClass}">
        <i class="fas fa-arrow-right"></i>
      </div>

      <div class="version-card latest-version">
        <div class="version-status status-latest">${latestStatusText}</div>
        <h3><i class="fas fa-star"></i> 最新版本</h3>
        <div class="version-number">${rb}</div>
        <div class="version-date">远程仓库</div>
      </div>
    </div>

    <div class="content-container">
      <div class="status-alert ${statusClass}">
        <i class="fas ${isNew ? 'fa-exclamation-triangle' : 'fa-check-circle'}"></i>
        ${statusText}
      </div>

      ${isNew ? `<div class="button-group">${btnHtml}</div>` : ''}
    </div>
  </div>
</body>
</html>
    `;

    java.startBrowser('data:text/html;base64,' + java.base64Encode(html), '更新检测');
}

