    var content = novelBox.querySelector('.content');
    var next = document.querySelector('.nextbtn');

    var themes = [
      { name: '护眼', bg: '#f5f0e8', color: '#5b4636', title: '#3e2723', btn: '#8d6e63', btnText: '#fff', border: '#a1887f' },
      { name: '简约', bg: '#ffffff', color: '#333333', title: '#111111', btn: '#555555', btnText: '#fff', border: '#999999' },
      { name: '羊皮纸', bg: '#f4ecd8', color: '#6b5b3e', title: '#4a3728', btn: '#a08050', btnText: '#fff', border: '#c4a86c' },
      { name: '绿护眼', bg: '#e8f0e8', color: '#3a4a3a', title: '#2d3d2d', btn: '#6a9a6a', btnText: '#fff', border: '#8cb88c' },
      { name: '夜间', bg: '#1a1a1a', color: '#d0d0d0', title: '#e0e0e0', btn: '#2d2d2d', btnText: '#e0e0e0', border: '#444444' }
    ];
    var curIdx = 0;
    try { curIdx = parseInt(localStorage.getItem('novelTheme')) || 0; } catch(e) {}
    if (curIdx >= themes.length) curIdx = 0;

    function applyTheme(idx) {
      var t = themes[idx];
      document.body.style.cssText = 'margin:0;padding:0 0 60px;background:' + t.bg + ';transition:background 0.3s;';
      var el;
      el = document.getElementById('novel-title');
      if (el) el.style.cssText = 'font-size:20px;font-weight:bold;color:' + t.title + ';padding:20px 16px 8px;margin:0;line-height:1.4;text-align:center;';
      el = document.getElementById('novel-content');
      if (el) {
        var ps = el.querySelectorAll('p');
        for (var i = 0; i < ps.length; i++) {
          ps[i].style.cssText = 'font-size:17px;line-height:1.9;color:' + t.color + ';padding:6px 20px;margin:0;text-indent:2em;transition:color 0.3s;';
        }
      }
      el = document.getElementById('theme-btn');
      if (el) {
        el.textContent = t.name;
        el.style.cssText = 'position:fixed;bottom:12px;right:12px;z-index:9999;background:' + t.btn + ';color:' + t.btnText + ';border:1px solid ' + t.border + ';padding:6px 14px;border-radius:20px;font-size:13px;box-shadow:0 2px 8px rgba(0,0,0,0.15);';
      }
      el = document.getElementById('next-btn');
      if (el) {
        el.style.cssText = 'display:block;width:calc(100% - 48px);margin:0 24px;padding:14px 0;font-size:16px;text-align:center;background:' + t.btn + ';color:' + t.btnText + ';border:1px solid ' + t.border + ';border-radius:8px;text-decoration:none;';
      }
      try { localStorage.setItem('novelTheme', idx); } catch(e) {}
    }

    var h = '';

    if (title) {
      h += '<h1 id="novel-title">' + title.innerText + '</h1>';
    }

    if (content) {
      h += '<div id="novel-content">';
      var ps = content.querySelectorAll('p');
      for (var i = 0; i < ps.length; i++) {
        h += '<p>' + ps[i].innerHTML + '</p>';
      }
      h += '</div>';
    }

    if (next) {
      var nextHref = next.querySelector('a') ? next.querySelector('a').href : '#';
      h += '<a id="next-btn" href="' + nextHref + '">下一章 →</a>';
    }

    h += '<button id="theme-btn"></button>';

    document.body.innerHTML = h;

    document.getElementById('theme-btn').addEventListener('click', function() {
      curIdx = (curIdx + 1) % themes.length;
      applyTheme(curIdx);
    });

    applyTheme(curIdx);
    return;
  }

})();

