   var rawUrl = String(baseUrl || source.sourceUrl);
   var match = rawUrl.match(/^(https?:\/\/[^\/]+)/);
   var sUrl = match ? match[1] : String(source.sourceUrl).replace(/\/+$/, '');

   var sk = source.getVariable() || '我的';

   function decodeBase64(res){
       var i = res.indexOf('var a="');
       if(i !== -1){
           i += 7;
           var j = res.indexOf('"', i);
           if(j !== -1) return java.base64Decode(res.substring(i, j));
       }
       return res;
   }

   var html = decodeBase64(result);

   var isVerify = html.indexOf('请输入验证码') > -1 
               || html.indexOf('mac_verify') > -1 
               || html.indexOf('verify/index.html') > -1
               || html.indexOf('captcha') > -1;

   if(isVerify){
       java.log('触发验证码，当前域名:' + sUrl);

       var captchaUrl = sUrl + '/index.php/verify/index.html?t=' + Date.now();
       java.log('验证码图:' + captchaUrl);

       var yzco = cache.get('yzm');
       var doVerify = function(code){
           var checkUrl = sUrl + '/index.php/ajax/verify_check?type=search&verify=' + encodeURIComponent(code);
           var referer = sUrl + '/vod/search/page/1/tid/2/wd/' + encodeURIComponent(sk) + '.html';
           var postUrl = checkUrl + ',{"method":"POST","headers":{"Referer":"' + referer + '","X-Requested-With":"XMLHttpRequest","Content-Type":"application/x-www-form-urlencoded"}}';
           return java.ajax(postUrl);
       };

       var doSearch = function(){
           result = java.ajax(sUrl + '/vod/search/page/1/tid/2/wd/' + encodeURIComponent(sk) + '.html');
           return decodeBase64(result);
       };

       var vr = '';
       if(yzco && yzco != ''){
           java.log('尝试复用旧验证码:' + yzco);
           vr = doVerify(yzco);
           java.log('旧验证码验证返回:' + vr);
           try {
               var json = JSON.parse(vr);
               if(json.code === 1){
                   java.log('旧验证码有效，搜索词:' + sk);
                   html = doSearch();
                   cache.put('yzm', yzco, 3600);
               } else {
                   java.log('旧验证码过期，重新获取');
                   throw new Error('expired');
               }
           } catch(e){
               var yzm = java.getVerificationCode(captchaUrl);
               if(!yzm || yzm === ''){
                   java.longToast('验证码加载失败，改用浏览器');
                   java.startBrowser(sUrl + '/vod/search/page/1/tid/2/wd/' + encodeURIComponent(sk) + '.html', '请完成验证后返回');
                   return [];
               }
               java.log('输入:' + yzm);
               vr = doVerify(yzm);
               java.log('新验证码验证返回:' + vr);
               try {
                   var json2 = JSON.parse(vr);
                   if(json2.code !== 1){
                       java.log('验证失败，code=' + json2.code + ', msg=' + (json2.msg || '无'));
                       return [];
                   }
                   cache.put('yzm', yzm, 3600);
                   java.log('验证通过，搜索词:' + sk);
                   html = doSearch();
               } catch(e2){
                   java.log('验证返回不是有效JSON:' + vr);
                   return [];
               }
           }
       } else {
           var yzm = java.getVerificationCode(captchaUrl);
           if(!yzm || yzm === ''){
               java.longToast('验证码加载失败，改用浏览器');
               java.startBrowser(sUrl + '/vod/search/page/1/tid/2/wd/' + encodeURIComponent(sk) + '.html', '请完成验证后返回');
               return [];
           }
           java.log('输入:' + yzm);
           vr = doVerify(yzm);
           java.log('验证返回:' + vr);
           try {
               var json = JSON.parse(vr);
               if(json.code !== 1){
                   java.log('验证失败，code=' + json.code + ', msg=' + (json.msg || '无'));
                   return [];
               }
               cache.put('yzm', yzm, 3600);
               java.log('验证通过，搜索词:' + sk);
               html = doSearch();
           } catch(e){
               java.log('验证返回不是有效JSON:' + vr);
               return [];
           }
       }
   }

   java.setContent(html);
   return java.getElements('.module-poster-item');
})()

